export interface Scenario {
  customer: { yearsWithMHPCO: number };
  steps: Step[];
}

export interface Step {
  op: string;
  items?: unknown[];
  policy?: number;
  incident?: unknown;
}

export interface QuoteResult {
  premium: number;
}

export interface ScenarioResults {
  results: QuoteResult[];
}

const BASE_PREMIUMS: Record<string, number> = { sword: 100 };

const PROCESSING_FEE = 5;

/**
 * The first-insurance surcharge is +10%, applied as the exact ratio 11/10
 * rather than a 1.1 multiplier. Floating-point `100 * 1.1` is
 * 110.00000000000001, which rounds up to 111 and yields a 116 G premium
 * instead of 115 G. Multiplying before dividing keeps the arithmetic exact.
 */
const FIRST_INSURANCE_SURCHARGE = { numerator: 11, denominator: 10 };

const applyFirstInsuranceSurcharge = (amount: number): number =>
  (amount * FIRST_INSURANCE_SURCHARGE.numerator) /
  FIRST_INSURANCE_SURCHARGE.denominator;

/** All rounding is in the MHPCO's favor — always up. */
const roundInMHPCOsFavor = Math.ceil;

export const runScenario = (scenario: Scenario): ScenarioResults => {
  return {
    results: scenario.steps.map((step) => {
      const items = (step.items ?? []) as { type: string }[];
      const base = items.reduce(
        (sum, item) => sum + BASE_PREMIUMS[item.type],
        0,
      );

      const surcharged = applyFirstInsuranceSurcharge(base);

      return { premium: roundInMHPCOsFavor(surcharged) + PROCESSING_FEE };
    }),
  };
};

