const isBuildingBlock = (items: InsuredItem[]): boolean =>
  items.length === BUILDING_BLOCK_SIZE &&
  items.every((item) => item.type === items[0].type);

const sumBasePremiums = (items: InsuredItem[]): number => {
  if (isBuildingBlock(items)) return BUILDING_BLOCK_PREMIUM;

  return items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
};

