export interface Scenario {
  customer: { yearsWithMHPCO: number };
  steps: Step[];
}

export interface InsuredItem {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface Step {
  op: string;
  items?: InsuredItem[];
  policy?: number;
  incident?: unknown;
}

export interface QuoteResult {
  premium: number;
}

export interface ScenarioResults {
  results: QuoteResult[];
}

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const PROCESSING_FEE = 5;

const WHOLE_PERCENT = 100;

/**
 * Surcharges multiply before dividing, so the arithmetic stays exact.
 * A 1.1 multiplier would not: floating-point `100 * 1.1` is
 * 110.00000000000001, which rounds up to 111 and yields a 116 G premium
 * instead of 115 G.
 */
const addSurcharge = (amount: number, surchargePercent: number): number =>
  (amount * (WHOLE_PERCENT + surchargePercent)) / WHOLE_PERCENT;

const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;

/** All rounding is in the MHPCO's favor — always up. */
const roundInMHPCOsFavor = Math.ceil;

const sumBasePremiums = (items: InsuredItem[]): number =>
  items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);

/**
 * The premium pipeline, in the order the spec states it: sum the base
 * premiums, apply surcharges, round, then add the processing fee last.
 */
const quotePremium = (step: Step): QuoteResult => {
  const basePremium = sumBasePremiums(step.items ?? []);
  const surcharged = addSurcharge(
    basePremium,
    FIRST_INSURANCE_SURCHARGE_PERCENT,
  );

  return { premium: roundInMHPCOsFavor(surcharged) + PROCESSING_FEE };
};

export const runScenario = (scenario: Scenario): ScenarioResults => ({
  results: scenario.steps.map(quotePremium),
});

