    expect(result).toEqual({ results: [{ premium: 99 }] });
  });
  it("does not form a building block from 3 components of different kinds — 2 runes + 1 moonstone = 75 G, +10% rounded up, +5 G fee = 88 G", () => {
    const rune = {
      type: "rune",
      material: "stone",
      enchantment: 1,
      cursed: false,
