  it("adds a 50% risk surcharge for a cursed item — cursed sword 100 G -> 150 G, +10%, +5 G fee = 170 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [
            { type: "sword", material: "steel", enchantment: 1, cursed: true },
          ],
        },
      ],
