  });
  it.todo("adds a 30% risk surcharge for a highly enchanted item (enchantment >= 5) — sword at 5 = 130 G");
  it.todo("does not add the enchantment surcharge below level 5 — sword at 4 = 100 G");
  it.todo("adds both surcharges for a cursed and highly enchanted item — sword = 180 G");

  // --- Quoting: customer modifiers -----------------------------------------
  it.todo("gives a 20% loyalty discount for a customer with >= 2 years — sword = 80 G");
  it.todo("gives no loyalty discount below 2 years with MHPCO — sword = 100 G");
  it.todo("adds a 10% initial assessment surcharge on the first insurance — sword = 110 G");
  it.todo("gives a 15% discount on each contract after the first — second quote of a sword = 85 G");

  // --- Quoting: processing fee and rounding --------------------------------
  it.todo("adds the 5 G processing fee after all modifiers");
  it.todo("rounds the premium up, in the MHPCO's favor");

  // --- Quoting: combinations -----------------------------------------------
  it.todo("combines surcharges, loyalty discount, first-insurance surcharge and fee in one quote");

  // --- Claims: basics -------------------------------------------------------
  it.todo("pays a claim minus the 100 G deductible per damage event — 200 G damage pays 100 G");
  it.todo("pays nothing when the damage does not exceed the deductible — 100 G damage pays 0 G");
  it.todo("applies the deductible once per incident, not per damaged item");
  it.todo("reports the remaining cap after a claim — twice the insurance sum minus payout");

  // --- Claims: reimbursement rules -----------------------------------------
  it.todo("reimburses damage to an item with enchantment >= 8 at 50% of the damage amount");
  it.todo("fully reimburses damage to an item made of dragon material");
  it.todo("fully reimburses dragon material even when the item is highly enchanted");

  // --- Claims: cap ----------------------------------------------------------
  it.todo("caps the total payout per policy at twice the insurance sum");
  it.todo("reduces the remaining cap across successive claims on the same policy");
  it.todo("pays nothing once the cap is exhausted — remaining cap stays 0");

  // --- Scenarios ------------------------------------------------------------
  it.todo("processes the spec's quote-only scenario — one result with a premium");
  it.todo("processes the spec's quote-then-two-claims scenario in order");
  it.todo("keeps separate caps for two policies of the same customer");
});

