export interface Scenario {
  customer: { yearsWithMHPCO: number };
  steps: Step[];
}

export interface InsuredItem {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface Step {
  op: string;
  items?: InsuredItem[];
  policy?: number;
  incident?: unknown;
}

export interface QuoteResult {
  premium: number;
}

export interface ScenarioResults {
  results: QuoteResult[];
}

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const PROCESSING_FEE = 5;

const WHOLE_PERCENT = 100;

/**
 * Surcharges multiply before dividing, so the arithmetic stays exact.
 * A 1.1 multiplier would not: floating-point `100 * 1.1` is
 * 110.00000000000001, which rounds up to 111 and yields a 116 G premium
 * instead of 115 G.
 */
const addSurcharge = (amount: number, surchargePercent: number): number =>
  (amount * (WHOLE_PERCENT + surchargePercent)) / WHOLE_PERCENT;

const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;

/** All rounding is in the MHPCO's favor — always up. */
const roundInMHPCOsFavor = Math.ceil;

const BUILDING_BLOCK_SIZE = 3;
const BUILDING_BLOCK_PREMIUM = 60;

/** Only items of one and the same kind group into a block. */
const areAllTheSameKind = ([first, ...rest]: InsuredItem[]): boolean =>
  first !== undefined && rest.every((item) => item.type === first.type);

/**
 * How many flat-rate blocks this list forms. A mixed list forms none — only
 * alike items group — and so does any list too short to fill one block.
 */
const countCompleteBlocks = (items: InsuredItem[]): number =>
  areAllTheSameKind(items) ? Math.floor(items.length / BUILDING_BLOCK_SIZE) : 0;

const CURSED_SURCHARGE_PERCENT = 50;
const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
const HIGH_ENCHANTMENT_LEVEL = 5;

/** A risk rule contributes its percent only when the item trips it. */
const percentWhen = (applies: boolean, percent: number): number =>
  applies ? percent : 0;

const isHighlyEnchanted = (item: InsuredItem): boolean =>
  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;

/** Risk surcharges add to the base premium; they do not compound. */
const riskSurchargePercentFor = (item: InsuredItem): number =>
  percentWhen(item.cursed === true, CURSED_SURCHARGE_PERCENT) +
  percentWhen(isHighlyEnchanted(item), HIGH_ENCHANTMENT_SURCHARGE_PERCENT);

/** An item's list price with its own risk surcharges applied. */
const riskAdjustedPremiumFor = (item: InsuredItem): number =>
  addSurcharge(BASE_PREMIUMS[item.type], riskSurchargePercentFor(item));

const sumRiskAdjustedPremiums = (items: InsuredItem[]): number =>
  items.reduce((sum, item) => sum + riskAdjustedPremiumFor(item), 0);

/**
 * Prices an item list: alike items are grouped into building blocks sold at a
 * flat rate, and whatever is left over is priced item by item, each at its own
 * risk-adjusted premium.
 */
const priceItems = (items: InsuredItem[]): number => {
  const blocks = countCompleteBlocks(items);
  const leftovers = items.slice(blocks * BUILDING_BLOCK_SIZE);

  return blocks * BUILDING_BLOCK_PREMIUM + sumRiskAdjustedPremiums(leftovers);
};

/**
 * The premium pipeline, in the order the spec states it: price the items,
 * apply surcharges, round, then add the processing fee last.
 */
const quotePremium = (items: InsuredItem[]): QuoteResult => {
  const surcharged = addSurcharge(
    priceItems(items),
    FIRST_INSURANCE_SURCHARGE_PERCENT,
  );

  return { premium: roundInMHPCOsFavor(surcharged) + PROCESSING_FEE };
};

export const runScenario = (scenario: Scenario): ScenarioResults => ({
  results: scenario.steps.map((step) => quotePremium(step.items ?? [])),
});

