const DEDUCTIBLE = 100;
const CAP_MULTIPLE = 2;

const insuranceSumOf = (items: InsuredItem[]): number =>
  items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);

const settleClaim = (incident: Incident, insuredItems: InsuredItem[]): ClaimResult => {
  const damage = incident.damages.reduce((sum, d) => sum + d.amount, 0);
  const payout = Math.max(0, damage - DEDUCTIBLE);

  return {
    payout,
    remainingCap: CAP_MULTIPLE * insuranceSumOf(insuredItems) - payout,
  };
};

export const runScenario = (scenario: Scenario): ScenarioResults => ({
  results: scenario.steps.map((step, stepIndex) => {
    if (step.op === "claim") {
      const policy = scenario.steps[step.policy ?? 0];

      return settleClaim(step.incident!, policy.items ?? []);
    }

    return quotePremium(
      step.items ?? [],
      scenario.customer,
      isFirstContractAtStep(stepIndex),
    );
  }),
});

