        op: "claim",
        policy: 0,
        incident: {
          cause: "dragon fire",
          damages: [{ itemType: "sword", amount: 400 }],
        },
      },
    ],
  });

  expect(result).toEqual({
    results: [{ premium: 115 }, { payout: 300, remainingCap: 1700 }],
  });
});

