it("reduces the remaining cap across successive claims on the same policy", () => {
  const result = runScenario({
    customer: { yearsWithMHPCO: 5 },
    steps: [
      {
        op: "quote",
        items: [
          {
            type: "amulet",
            material: "silver",
            enchantment: 2,
            cursed: false,
          },
        ],
      },
      {
        op: "claim",
        policy: 0,
        incident: {
          cause: "fire",
          damages: [{ itemType: "amulet", amount: 200 }],
        },
      },
      {
        op: "claim",
        policy: 0,
        incident: {
          cause: "spell mishap",
          damages: [{ itemType: "amulet", amount: 250 }],
        },
      },
    ],
  });

  expect(result).toEqual({
    results: [
      { premium: 58 },
      { payout: 100, remainingCap: 1100 },
      { payout: 150, remainingCap: 950 },
    ],
  });
});

