export const runScenario = ({
  customer,
  steps,
}: Scenario): ScenarioResults => {
  const remainingCaps = new Map<number, number>();

  return {
    results: steps.map((step, stepIndex) => {
      if (step.op !== "claim") {
        return quotePremium(
          step.items,
          customer,
          isFirstContractAtStep(stepIndex),
        );
      }

      const insuredItems = itemsCoveredBy(step, steps);
      const capBefore = remainingCaps.get(step.policy) ?? capOf(insuredItems);
      const result = settleClaim(step.incident, insuredItems, capBefore);

      remainingCaps.set(step.policy, result.remainingCap);

      return result;
    }),
  };
};

